select cast(order_purchase_timestamp as date) order_date,customer_state,is_purchase_holiday,count(*) orders,avg(actual_delivery_days::decimal(18,2)) avg_delivery_days,avg(delivery_variance_days::decimal(18,2)) avg_delivery_variance_days,avg(carrier_handoff_days::decimal(18,2)) avg_carrier_handoff_days,sum(case when is_late_delivery then 1 else 0 end)::decimal(18,2)/nullif(count(*),0) late_delivery_rate from {{ ref('fct_orders') }} group by 1,2,3
